Basic:
import { TreeSelect } from 'vellum-ui'

const teams = [
  {
    value: 'product',
    title: 'Product',
    children: [
      { value: 'design', title: 'Design' },
      { value: 'dev', title: 'Engineering' },
    ],
  },
  { value: 'marketing', title: 'Marketing' },
]

export function Basic() {
  return (
    <TreeSelect
      block
      showSearch
      allowClear
      defaultExpandAll
      placeholder="Select a team"
      options={teams}
    />
  )
}

Checkable:
import { TreeSelect } from 'vellum-ui'

const teams = [
  {
    value: 'product',
    title: 'Product',
    children: [
      { value: 'design', title: 'Design' },
      { value: 'dev', title: 'Engineering' },
    ],
  },
  { value: 'marketing', title: 'Marketing' },
]

export function Checkable() {
  return (
    <TreeSelect
      block
      multiple
      checkable
      showChecked="parent"
      defaultExpandAll
      placeholder="Select who can see it"
      options={teams}
    />
  )
}
